WITH recent_suppliers AS (SELECT * FROM suppliers WHERE country != 'UK'), city_summary AS (SELECT city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating, ROUND(AVG(rating), 2) AS avg_rating FROM recent_suppliers GROUP BY city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END) SELECT city, rating_bucket, total_rating FROM city_summary WHERE total_rating >= 14 ORDER BY rating_bucket, total_rating DESC;
